{
  "daemon": {
    "port": 6767
  },
  "agents": {
    "providers": {
      "my-claude": {
        "extends": "claude",
        "label": "Mine",
        "env": {
          "ANTHROPIC_BASE_URL": "https://example.com"
        }
      },
      "astra": {
        "extends": "claude",
        "label": "Astra",
        "description": "Claude Code through the Astra gateway",
        "env": {
          "ANTHROPIC_BASE_URL": "https://astra.corp.com",
          "ANTHROPIC_AUTH_TOKEN": "sk-someone-else"
        },
        "disallowedTools": [
          "WebSearch"
        ],
        "models": [
          {
            "id": "deepseek-chat",
            "label": "DeepSeek Chat"
          },
          {
            "id": "claude-sonnet-4-5",
            "label": "Claude Sonnet 4.5",
            "isDefault": true
          }
        ]
      },
      "astra-codex": {
        "extends": "codex",
        "label": "Astra (Codex)",
        "description": "Codex through the Astra gateway, for models served over the Responses API",
        "env": {
          "OPENAI_BASE_URL": "https://astra.corp.com",
          "OPENAI_API_KEY": "sk-astra-enterprise-key"
        },
        "models": [
          {
            "id": "gpt-5",
            "label": "GPT-5",
            "isDefault": true
          }
        ]
      }
    }
  }
}
